1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
28	
29	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	const basePremiumPerItemOf = (itemType: string): number =>
39	  BASE_PREMIUM_BY_ITEM_TYPE[itemType];
40	
41	// Percentages are always taken as `amount * percent / 100`, never `amount * 1.15`:
42	// exact fractional intermediates, a single rounding at the very end.
43	const percentOf = (amount: number, percent: number): number =>
44	  (amount * percent) / 100;
45	
46	const COMPONENT_BLOCK_SIZE = 3;
47	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
48	
49	const countByItemType = (items: Item[]): Map<string, number> =>
50	  items.reduce(
51	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
52	    new Map<string, number>(),
53	  );
54	
55	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
56	
57	const isComponent = (itemType: string): boolean =>
58	  COMPONENT_TYPES.has(itemType);
59	
60	const basePremiumForCountOf = (itemType: string, count: number): number =>
61	  isComponent(itemType) && count === COMPONENT_BLOCK_SIZE
62	    ? COMPONENT_BLOCK_BASE_PREMIUM
63	    : count * basePremiumPerItemOf(itemType);
64	
65	const sum = (amounts: number[]): number =>
66	  amounts.reduce((total, amount) => total + amount, 0);
67	
68	const policyBasePremiumOf = (items: Item[]): number =>
69	  sum(
70	    [...countByItemType(items)].map(([itemType, count]) =>
71	      basePremiumForCountOf(itemType, count),
72	    ),
73	  );
74	
75	const CURSE_SURCHARGE_PERCENT = 50;
76	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
77	const HIGH_ENCHANTMENT_LEVEL = 5;
78	
79	const isHighlyEnchanted = (item: Item): boolean =>
80	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
81	
82	const itemSurchargePercentOf = (item: Item): number =>
83	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
84	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
85	
86	// Item-level modifiers apply to the affected ITEM's own base premium.
87	const itemSurchargesOf = (items: Item[]): number =>
88	  sum(
89	    items.map((item) =>
90	      percentOf(basePremiumPerItemOf(item.type), itemSurchargePercentOf(item)),
91	    ),
92	  );
93	
94	const LOYALTY_DISCOUNT_PERCENT = 20;
95	const LOYALTY_YEARS = 2;
96	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
97	
98	const isLongStanding = (customer: Customer): boolean =>
99	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
100	
101	// Policy-wide modifiers are signed percentages OF THE POLICY BASE PREMIUM (the sum
102	// of item base premiums) — never of the running total, so item surcharges stay
103	// outside their scope. Positive is a surcharge, negative a discount. Adding a
104	// policy-wide modifier means adding one entry here.
105	const policyModifierPercentsOf = (
106	  customer: Customer,
107	  isFollowUpContract: boolean,
108	): number[] => [
109	  FIRST_INSURANCE_SURCHARGE_PERCENT,
110	  ...(isLongStanding(customer) ? [-LOYALTY_DISCOUNT_PERCENT] : []),
111	  ...(isFollowUpContract ? [-FOLLOW_UP_DISCOUNT_PERCENT] : []),
112	];
113	
114	const quotePremium = (
115	  items: Item[],
116	  customer: Customer,
117	  isFollowUpContract: boolean,
118	): number => {
119	  const policyBasePremium = policyBasePremiumOf(items);
120	  const policyModifiers = sum(
121	    policyModifierPercentsOf(customer, isFollowUpContract).map((percent) =>
122	      percentOf(policyBasePremium, percent),
123	    ),
124	  );
125	
126	  // The processing fee is added last, after every modifier.
127	  return Math.ceil(
128	    policyBasePremium +
129	      itemSurchargesOf(items) +
130	      policyModifiers +
131	      PROCESSING_FEE,
132	  );
133	};
134	
135	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
136	  sword: 1000,
137	  amulet: 600,
138	  staff: 800,
139	  potion: 400,
140	  rune: 250,
141	  moonstone: 250,
142	};
143	
144	const DEDUCTIBLE_PER_DAMAGE = 100;
145	const CAP_MULTIPLIER = 2;
146	
147	const insuranceSumOf = (items: Item[]): number =>
148	  sum(items.map((item) => INSURANCE_VALUE_BY_ITEM_TYPE[item.type]));
149	
150	const payoutForDamage = (damage: Damage): number =>
151	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
152	
153	export const runScenario = (scenario: Scenario): StepResult[] => {
154	  let quotesSoFar = 0;
155	  const insuredItemsByStep = new Map<number, Item[]>();
156	
157	  return scenario.steps.map((step, stepIndex) => {
158	    if (step.op === "quote") {
159	      const premium = quotePremium(
160	        step.items,
161	        scenario.customer,
162	        quotesSoFar > 0,
163	      );
164	      quotesSoFar += 1;
165	      insuredItemsByStep.set(stepIndex, step.items);
166	      return { premium };
167	    }
168	
169	    const insuredItems = insuredItemsByStep.get(step.policy)!;
170	    const cap = CAP_MULTIPLIER * insuranceSumOf(insuredItems);
171	    const payout = Math.floor(sum(step.incident.damages.map(payoutForDamage)));
172	
173	    return { payout, remainingCap: cap - payout };
174	  });
175	};
