const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLIER = 2;

const insuranceSumOf = (items: Item[]): number =>
  sum(items.map((item) => INSURANCE_VALUE_BY_ITEM_TYPE[item.type]));

const payoutForDamage = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

// A policy is what a quote step leaves behind for later claim steps to draw on:
// the insured items and the cap those items entitle the holder to. `remainingCap`
// is the only thing a claim consumes, so it is the one mutable field.
type Policy = {
  insuredItems: Item[];
  remainingCap: number;
};

const issuePolicy = (insuredItems: Item[]): Policy => ({
  insuredItems,
  remainingCap: CAP_MULTIPLIER * insuranceSumOf(insuredItems),
});

const settleClaim = (policy: Policy, damages: Damage[]): StepResult => {
  const payout = Math.floor(sum(damages.map(payoutForDamage)));

  return { payout, remainingCap: policy.remainingCap - payout };
};

export const runScenario = (scenario: Scenario): StepResult[] => {
  // Policies accumulate in step order, so a claim's `policy` index is the index of
  // the quote step that issued it.
  const policies: Policy[] = [];

  return scenario.steps.map((step) => {
    if (step.op === "claim") {
      return settleClaim(policies[step.policy]!, step.incident.damages);
    }

    const premium = quotePremium(
      step.items,
      scenario.customer,
      policies.length > 0,
    );
    policies.push(issuePolicy(step.items));

    return { premium };
  });
};

